pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        vm.prank(caller);
        uint256 balanceBefore = c.tokenBalance(caller);

        // We need to call airDrop, but it requires hasNoBalance modifier (balance == 0) and supportsToken (msg.sender must be a Bank)
        // To satisfy supportsToken, we deploy a Bank and set caller to that address
        Bank bank = new Bank();
        vm.prank(address(bank));

        // However, the caller is the Bank contract, not an arbitrary address. So we fuzz the caller as the Bank address.
        // We'll redeploy Bank each time for simplicity.

        // Actually, we need to call airDrop from the Bank contract address, and the Bank contract must have zero balance.
        // So let's set up properly:
        address bankAddr = address(bank);
        vm.assume(c.tokenBalance(bankAddr) == 0);

        vm.prank(bankAddr);
        // Before calling, record balance
        uint256 balBefore = c.tokenBalance(bankAddr);

        c.airDrop();

        uint256 balAfter = c.tokenBalance(bankAddr);

        // The general rule: after airdrop, the balance should be exactly balBefore + 20 (since the reference adds 20)
        assertTrue(balAfter == balBefore + 20, "Balance should increase by exactly 20");
    }
}

