import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address bank) public {
        vm.assume(caller != address(0) && bank != address(0));
        vm.assume(caller != bank);
        // Fund the bank so it can act as msg.sender
        vm.deal(bank, 1 ether);

        // Ensure the bank contract supports the token
        // First deploy a Bank contract at an address that can be msg.sender
        // We'll use vm.prank to set caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("airDrop()"));
        // After the call (whether it reverted or succeeded), check that _locked is false
        bool locked = c._locked();
        assertTrue(!locked, "_locked should be false after a call to airDrop()");
    }
}

